def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    vans = image_patch.find("van")
    buses = image_patch.find("bus")

    if not vans or not buses:
        return image_patch

    next_to = []
    for van in vans:
        for bus in buses:
            if abs(van.horizontal_center - bus.horizontal_center) < min(van.width, bus.width) / 2:
                next_to.append(van)
                break

    return next_to[0] if next_to else vans[0]

